G=load()
def solve(Ag):
    A=np.array(Ag); H,W=A.shape
    nbg=int(np.bincount(A.flatten()).argmax())
    mask=(A!=nbg)
    pts=np.argwhere(mask)
    R0,R1=pts[:,0].min(),pts[:,0].max()
    C0,C1=pts[:,1].min(),pts[:,1].max()
    O=A.copy()
    def ray(r,c,dr,dc):
        i,j=r+dr,c+dc
        while 0<=i<H and 0<=j<W and not mask[i,j]:
            O[i,j]=4; i+=dr;j+=dc
    for r in range(R0,R1+1):
        for c in range(C0,C1+1):
            if A[r,c]==nbg: O[r,c]=4
    for fixval,name in [(C0,'L'),(C1,'R')]:
        gaps=[r for r in range(R0,R1+1) if A[r,fixval]==nbg]
        if not gaps: continue
        dc=-1 if name=='L' else 1
        mid=sum(gaps)/len(gaps)
        for r in gaps:
            ray(r,fixval,0,dc)
        for r0 in (gaps[0],gaps[-1]):
            dr={True:-1,False:1}[r0<mid]
            ray(r0,fixval,dr,dc)
    for fixval,name in [(R0,'T'),(R1,'B')]:
        gaps=[c for c in range(C0,C1+1) if A[fixval,c]==nbg]
        if not gaps: continue
        dr=-1 if name=='T' else 1
        mid=sum(gaps)/len(gaps)
        for c in gaps:
            ray(fixval,c,dr,0)
        for c0 in (gaps[0],gaps[-1]):
            dc2={True:-1,False:1}[c0<mid]
            ray(fixval,c0,dr,dc2)
    return O
for k in ('Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4'):
    got=solve(G[k+' input']); O=np.array(G[k+' output'])
    d=got!=O; print(k,f'{int(d.sum())} mismatches')
    if d.any():
        for i,j in np.argwhere(d)[:8]:
            print('  at',(int(i),int(j)),'got',got[i,j],'want',O[i,j])
